mapper.select:
select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name as pParentName, parent.P_Name_History as pParentNameHistory, parent.P_code as pParentCode,
from Pre_Project_Change mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID ${params.authSql} and mn.deleted = false
order by ISNULL(mn.${params.sortFiled}),mn.${params.sortFiled} ${params.sortType}
order by ISNULL(${params.sortSideFiled}),${params.sortSideFiled} ${params.sortType}
order by mn.Pc_Create_Time DESC
